import os
 from collections import Counter
from pathlib import Path
def read\_all\_files\_under\_directory(directory):
   files = os.listdir(directory)
   for file in files:
     if os.path.isfile(os.path.join(directory, file)):
       with open(os.path.join(directory, file), 'r') as file:
         content = file.read()
       for word in content.split():
         if len(word) > 0:
           yield word

def top\_5\_words(directory):
   words = Counter()
   for file in read\_all\_files\_under\_directory(directory):
     words.update(file)
   return words.most\_common(5)


